const b = $json.body;
if (!b || Object.keys(b).sort().join(',') !== 'contract,deadline,domain,operation_id,purpose' ||
    b.contract !== 'chief.handshake.v1' || b.purpose !== 'synthetic-handshake-only' ||
    typeof b.operation_id !== 'string' || !/^[a-f0-9]{32}$/.test(b.operation_id) ||
    typeof b.domain !== 'string' || !/^[a-z][a-z0-9_-]{0,63}$/.test(b.domain) ||
    typeof b.deadline !== 'number' || !Number.isFinite(b.deadline) ||
    b.deadline <= Date.now()/1000 || b.deadline > Date.now()/1000 + 30) {
  throw new Error('Invalid or expired synthetic handshake');
}
return [{json:{contract:'chief.handshake.v1', operation_id:b.operation_id,
  domain:b.domain, status:'COMPLETED', result:'synthetic-handshake-only'}}];
